import{_ as a,o as t,c as r,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Practical Business Ceph Examples | Ceph Days NYC 2024","description":"","frontmatter":{"title":"Practical Business Ceph Examples | Ceph Days NYC 2024","date":"2024-05-23T00:00:00.000Z","updated":"2024-05-24T00:00:00.000Z","tags":["Ceph","分布式存储","中小型数据中心","实际应用案例","存储解决方案"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/Practical_Business_Ceph_Examples_Ceph_Days_NYC_2024.md","filePath":"posts/2024/Practical_Business_Ceph_Examples_Ceph_Days_NYC_2024.md","lastUpdated":1780459816000}'),l={name:"posts/2024/Practical_Business_Ceph_Examples_Ceph_Days_NYC_2024.md"};function o(i,e,h,n,p,c){return t(),r("div",null,[...e[0]||(e[0]=[s('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-ceph在中小型数据中心业务应用的探讨" tabindex="-1">会议主题：Ceph在中小型数据中心业务应用的探讨 <a class="header-anchor" href="#会议主题-ceph在中小型数据中心业务应用的探讨" aria-label="Permalink to &quot;会议主题：Ceph在中小型数据中心业务应用的探讨&quot;">​</a></h4><h4 id="参会人员-发言人姓名" tabindex="-1">参会人员：[发言人姓名] <a class="header-anchor" href="#参会人员-发言人姓名" aria-label="Permalink to &quot;参会人员：[发言人姓名]&quot;">​</a></h4><h4 id="会议时间-具体日期" tabindex="-1">会议时间：[具体日期] <a class="header-anchor" href="#会议时间-具体日期" aria-label="Permalink to &quot;会议时间：[具体日期]&quot;">​</a></h4><h4 id="会议地点-具体地点" tabindex="-1">会议地点：[具体地点] <a class="header-anchor" href="#会议地点-具体地点" aria-label="Permalink to &quot;会议地点：[具体地点]&quot;">​</a></h4><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><ol><li><strong>Ceph的应用误解</strong>：发言人指出，Ceph常被误解为仅适用于大型复杂项目，如CERN、Bloomberg或Digital Ocean。实际上，Ceph同样适用于中小型数据中心。</li><li><strong>中小型数据中心的挑战与需求</strong>：讨论了中小型数据中心不需要过多的存储节点和高性能，但低延迟仍然非常重要。</li><li><strong>实际应用案例分享</strong>： <ul><li><strong>A5亿客户案例</strong>：客户使用Ceph在OpenVMS集群上运行，对延迟非常敏感，24/7无停机容忍。</li><li><strong>Proxmox与Ceph结合</strong>：在医疗组织中广泛应用，提供稳定的虚拟化环境。</li><li><strong>Ceph与VMware集成</strong>：通过IceKazi和NFS实现Ceph与VMware的集成，提供高可用性。</li><li><strong>ZFS on Ceph</strong>：在某些场景下，ZFS与Ceph结合使用，提供高效的存储解决方案。</li><li><strong>Borg项目</strong>：一个数据去重项目，通过Ceph实现高效的数据存储。</li><li><strong>Kubernetes与Ceph集成</strong>：通过CSI和Helm Chart实现Kubernetes的持久卷管理。</li><li><strong>RGW应用</strong>：通过pfSense和HAProxy实现S3兼容的存储解决方案。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li><strong>Ceph的广泛适用性</strong>：确认Ceph不仅适用于大型项目，同样适用于中小型数据中心。</li><li><strong>实际应用的验证</strong>：通过多个实际案例，验证了Ceph在不同业务场景下的有效性和稳定性。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li><strong>进一步推广Ceph的应用</strong>：通过更多的案例研究和实际部署，推广Ceph在中小型数据中心的使用。</li><li><strong>技术支持与社区合作</strong>：继续加强Ceph社区的合作，提供更多的技术支持和资源。</li></ul><h4 id="其他备注" tabindex="-1">其他备注： <a class="header-anchor" href="#其他备注" aria-label="Permalink to &quot;其他备注：&quot;">​</a></h4><ul><li><strong>社区合作的重要性</strong>：强调了Ceph社区在技术支持和资源共享方面的重要性。</li><li><strong>技术细节的深入探讨</strong>：鼓励对Ceph的技术细节进行更深入的探讨和研究。</li></ul><h4 id="会议结束语" tabindex="-1">会议结束语： <a class="header-anchor" href="#会议结束语" aria-label="Permalink to &quot;会议结束语：&quot;">​</a></h4><p>发言人感谢大家的参与，并鼓励大家在Ceph社区中继续合作和交流，共同推动Ceph技术的发展和应用。</p>',15)])])}const C=a(l,[["render",o]]);export{d as __pageData,C as default};
